/**
 * Beschreiben Sie hier die Klasse Sudoku.
 * 
 * @author (Ihr Name) 
 * @version (eine Versionsnummer oder ein Datum)
 */
import sas.*;
import sasio.*;
import java.awt.Color;
public class Sudoku
{
    private Spielfeld spielfeld;
    private View view;
    private Spielposition markierung;
    private Button[] btnZahlen;
    private Button btnHilfen;
    private Button btnEingaben;
    private Button btnPruefen;

    public Sudoku()
    {
       view = new View(451, 550, "Sudoku");
       spielfeld = new Spielfeld();
       btnZahlen = new Button[9];
       for (int i = 0; i<9; i++) {
         int zahl = i+1;
         btnZahlen[i] = new Button(5+i*49, 455, 45, 45, ""+zahl, new Color(255,246,143));

       }    
       btnHilfen = new Button(5, 505, 140, 40, "Hilfen", new Color(191,239,255));
       btnEingaben = new Button(154, 505, 140, 40, "Zahlen",new Color(191,239,255));
       btnPruefen = new Button(304, 505, 140, 40, "Prüfen", new Color(191,239,255));
       btnHilfen.setActivated(false);
       int x = 0;
       int y = 0;
       markierung = new Spielposition(x,y);
       while (spielfeld.istFix(markierung) && x < 9 && y < 9){
           x = x + 1;
           if (x == 9) {
             x = 0;
             y = y + 1;
           }
           markierung.setzePosition(x,y);
       }    
       spielfeld.setzeHindernis(markierung.gibXPosition(),markierung.gibYPosition(), Color.PINK);
    }

    private void kachelKlickAktion(Spielposition pPos) {
        if (!spielfeld.istFix(pPos)) {      
              int x = pPos.gibXPosition();
              int y = pPos.gibYPosition();
              spielfeld.entferneHindernis(markierung.gibXPosition(), markierung.gibYPosition());
              spielfeld.setzeHindernis(pPos.gibXPosition(),pPos.gibYPosition(), Color.PINK);
              markierung.setzePosition(x, y);
        }
    }

    private void btnZahlenAktion(int pZahl) {
      if (!btnHilfen.getActivated()) {
          spielfeld.bearbeiteHilfe(markierung, pZahl);
      } else {
          spielfeld.bearbeiteZahl(markierung, pZahl);
     }
    }

    private void btnHilfenAktion() {
      btnHilfen.setActivated(false);
      btnEingaben.setActivated(true);
    }

    private void btnEingabenAktion() {
      btnHilfen.setActivated(true);
      btnEingaben.setActivated(false);
    }

    private void btnPruefenAktion() {
      spielfeld.pruefen();
    }

    public void spielen() {
        while (true) {
          Spielposition pos = spielfeld.gibKlickKachel();
          if (pos.gibXPosition()!=-1) {
              kachelKlickAktion(pos);
           }
          for (int i = 0; i<9; i++) {
              if (btnZahlen[i].clicked()) {
                 btnZahlenAktion(i+1);
              }
          if (btnHilfen.clicked()) {
              btnHilfenAktion();
          }
          if (btnEingaben.clicked()) {
              btnEingabenAktion();
          }
          if (btnPruefen.clicked()) {
             btnPruefenAktion();
          }
          view.wait(10);
         }
       }
    }

    public static void main(String[] args) {
      Sudoku sud = new Sudoku();
      sud.spielen();
    }
}

/**
 * Erzeugt eine Rasterfläche aus Objekten der Klasse Kachel in der angegebenen Größe
 * 
 * @author Klaus Dingemann
 * @version 24.02.2018
 */
import sas.*;
import java.awt.Color;
public class Rasterflaeche
{
    private int anzahlKachelnX;
    private int anzahlKachelnY;
    private int pixelBreite;
    private int pixelHoehe;
    private int kachelBreite;
    private int kachelHoehe;
    private Rectangle hintergrund;
    private Kachel[][] kacheln;

    public Rasterflaeche(int pAnzahlKachelnX, int pAnzahlKachelnY, double pPixelBreite, double pPixelHoehe, 
           Color pKachelfarbe)
    {
       anzahlKachelnX = pAnzahlKachelnY;
       anzahlKachelnY = pAnzahlKachelnY;
       kachelBreite = (int)pPixelBreite / pAnzahlKachelnX;
       kachelHoehe = (int)pPixelHoehe / pAnzahlKachelnY;
       pixelBreite = kachelBreite * anzahlKachelnX;
       pixelHoehe = kachelHoehe * anzahlKachelnY;
       hintergrund = new Rectangle(0, 0, pixelBreite, pixelHoehe, new Color(200, 200, 200));
       kacheln = new Kachel[anzahlKachelnX][anzahlKachelnY];
       for (int i = 0; i<anzahlKachelnX ;i++) {
           for (int j = 0; j < anzahlKachelnY; j++) {
               kacheln[i][j] = new Kachel(i,j,kachelBreite,kachelHoehe, pKachelfarbe);
            }
        }
    }

    public void schachBrett(Color pFarbe) {
           for (int i = 0; i< anzahlKachelnX ;i++) {
           for (int j = 0; j < anzahlKachelnY; j++) {
               if (i % 2 == 0 && j % 2  == 0 || i % 2 == 1 && j % 2 == 1) {
                   kacheln[i][j].setzeFarbe(pFarbe);
                }
            }
        }
    }

    public int kachelXInPixelX(int pX) {
       return pX*kachelBreite+1;
    }

    public int kachelYInPixelY(int pY) {
       return pY*kachelHoehe+1;
    }

    public int pixelXInKachelX(double pX) {
       return (int)pX / kachelBreite;
    }

    public int pixelYInKachelY(double pY) {
       return (int)pY / kachelHoehe;
    }

    public void setzeHindernis(int pX, int pY, Color pColor) {
        if (pX>=0 && pX < anzahlKachelnX && pY >= 0 && pY < anzahlKachelnY) {
            kacheln[pX][pY].setzteHindernis(pColor);
        }
    }

    public void entferneHindernis(int pX, int pY) {
        if (pX>=0 && pX < anzahlKachelnX && pY >= 0 && pY < anzahlKachelnY) {
            kacheln[pX][pY].entferneHindernis();
        }
    }

    public boolean istHindernis(int pX, int pY) {
        return kacheln[pX][pY].istHindernis();
    }

    public boolean istInnen(int pX, int pY) {
        boolean innen =  (pX>=0) && (pX<anzahlKachelnX) && (pY>=0) && (pY<anzahlKachelnY);
        return innen;
    }

    public int gibKachelBreite() {
        return kachelBreite;
    }

    public int gibKachelHoehe(){
        return kachelHoehe;
    }

    public Kachel gibKachel(int pX, int pY) {
        return kacheln[pX][pY];
    }

     public Spielposition gibKlickKachel() {
        Spielposition klickPosition = new Spielposition(-1,-1);   
        for (int i = 0; i<anzahlKachelnX; i++) {
              for (int j = 0; j<anzahlKachelnY; j++) {
                  if (gibKachel(i,j).clicked()) {
                      klickPosition.setzePosition(i,j);
                  }
                }
            }
         return klickPosition;
     }
}

import java.awt.Color;
import sas.*;
public class Kachel
{
    // Instanzvariablen - ersetzen Sie das folgende Beispiel mit Ihren Variablen
    private int x;
    private int y;
    private Color farbe;
    private boolean hindernis;
    private Rectangle rechteck;


    public Kachel(int pX, int pY, int pKachelBreite, int pKachelHoehe, Color pFarbe)
    {
        x = pX;
        y = pY;
        farbe = pFarbe;
        hindernis = false;
        rechteck = new Rectangle(pX*pKachelBreite+1, pY*pKachelHoehe+1, pKachelBreite - 2, pKachelHoehe - 2, pFarbe);
    }

    public void setzeFarbe(Color pFarbe) {
        rechteck.setColor(pFarbe);
    }

    public void setzteHindernis(Color pHindernisFarbe) {
      hindernis = true;
      rechteck.setColor(pHindernisFarbe);
    }

    public void entferneHindernis() {
        hindernis = false;
        rechteck.setColor(farbe);
    }

    public boolean istHindernis() {
        return hindernis;
    }

    public int gibX() {
        return x;
    }

    public int gibY() {
        return y;
    }

    public boolean clicked() {
      return rechteck.mousePressed();
    }
}

/**
 * Erzeugt das Sudoku-Spielfeld als UNterklasse der KLasse Rasterfläche
 * 
 * @author Klaus Dingemann
 * @version 24.02.2018
 */
import sas.*;
import sasio.*;
import java.awt.Color;
public class Spielfeld extends Rasterflaeche
{
    private SudokuFeld[] felder; 

    public Spielfeld()
    {
        super(9,9,450.0,450.0,Color.WHITE);
        new Rectangle(0, 0, 450, 2);
        new Rectangle(0, 149, 450, 3);
        new Rectangle(0, 299, 450, 3);
        new Rectangle(0, 448, 450, 2);
        new Rectangle(0, 0, 2, 450);
        new Rectangle(149, 0, 3, 450);
        new Rectangle(299, 0, 3, 450);
        new Rectangle(448, 0, 2, 450);
        String[] sudo = StringFileTools.loadFileInStringArray("sudoku.txt"); 
        int anzahl = sudo.length;
        int nr = Tools.randomNumber(0,anzahl-1);
        felder = new SudokuFeld[81];
        for (int i = 0; i<81; i++) {
            int x = i % 9;
            int y = i / 9;
            String kennzeichen = sudo[nr].substring(i*2,i*2+1);
            String loesung = sudo[nr].substring(i*2+1,i*2+2);
            boolean fix = false;
            if (kennzeichen.equals("#")) {
                fix = true;
            }
            felder[i] = new SudokuFeld(new Spielposition(x, y), loesung, fix);
        }
    }

    public void bearbeiteHilfe(Spielposition pPos, int pZahl) {
      int index = pPos.gibYPosition()*9 + pPos.gibXPosition();
      felder[index].zeigeVersteckeHilfe(pZahl-1);
    }

    public void bearbeiteZahl(Spielposition pPos, int pZahl) {
      int index = pPos.gibYPosition()*9 + pPos.gibXPosition();
      felder[index].zeigeVersteckeZahl(pZahl);
    }


    public boolean istFix(Spielposition pPos) {
        int index = pPos.gibYPosition()*9 + pPos.gibXPosition();
        return felder[index].istFix();
    }

    public void pruefen() {
      for (int i=0; i<81; i++) {
        felder[i].pruefe();
      }
    }


}

/**
 * Beschreiben Sie hier die Klasse SudokuFeld.
 * 
 * @author (Ihr Name) 
 * @version (eine Versionsnummer oder ein Datum)zahl
 */
import sas.*;
import java.awt.Color;
public class SudokuFeld
{
   private Text[] hilfen;
   private Text zahl;
   private String loesung;
   private boolean fix;

   public SudokuFeld(Spielposition pPos, String pLoesung, boolean pFix)
   {
      int x = pPos.gibXPosition();
      int y = pPos.gibYPosition();
      Rectangle rect = new Rectangle(x * 50 + 3, y * 50 + 3, 44, 44, Color.WHITE);
      zahl = new Text(x * 50 + 13, y * 50 + 4, "0");
      hilfen = new Text[9];
      for (int i = 0; i < 9; i++) {
         int zahl = i + 1;
         hilfen[i] = new Text(x * 50 + 8 + i % 3 * 15, y * 50 + 5 + i / 3 * 15, "" + zahl);
         hilfen[i].setFontMonospaced(false, 10);
         hilfen[i].setHidden(true);
      }
      loesung = pLoesung;
      fix = pFix;
      if (fix) {
         zahl.setText(loesung);
         zahl.setColor(Color.BLUE);
         zahl.setFontMonospaced(true, 40);
         zahl.setHidden(false);
      } else {
         zahl.setFontMonospaced(false, 40);
         zahl.setHidden(true);
      }
   }

   public void zeigeVersteckeZahl(int pZahl) {
      int num = Integer.parseInt(zahl.getText());
      if (pZahl == num) {
         zahl.setText("0");
      } else {
         zahl.setText("" + pZahl);
      }
      if (zahl.getText().equals("0")) {
         zahl.setHidden(true);
      } else {
         zahl.setHidden(false);
         zahl.setColor(Color.BLACK);
      }
      for (int i = 0; i < 9; i++) {
         hilfen[i].setHidden(true);
      } 
   }

   public void zeigeVersteckeHilfe(int pZahl) {
      if (zahl.getHidden()) 
         if (hilfen[pZahl].getHidden()) {
         hilfen[pZahl].setHidden(false);
      } else {
         hilfen[pZahl].setHidden(true);
      }
   }

   boolean istFix() {
      return fix;
   }


   public void pruefe() {
      if (!(zahl.getText().equals("0"))) {
         if (!(zahl.getText().equals(loesung))) {
            zahl.setColor(Color.RED);
         } else if (!fix) {
            zahl.setColor(new Color(0, 100, 0));
         }
      }
   }

}

public class Spielposition
{
    private int xPosition;
    private int yPosition;

    public Spielposition(int pX, int pY)
    {
        xPosition = pX;
        yPosition = pY;
    }

    public void setzePosition(int pXPos, int pYPos) 
    {
        xPosition = pXPos;
        yPosition = pYPos;
    }

    public int gibXPosition() {
        return xPosition;
    }

    public int gibYPosition() {
        return yPosition;
    }    

    public boolean istGleich(Spielposition pPos) {
       return pPos.gibXPosition() == this.gibXPosition() &&
              pPos.gibYPosition() == this.gibYPosition();
    }
}
